// SABR implied vols from QuantLib's sabrVolatility (Hagan et al. 2002),
// lognormal and normal, for tests/fixtures/sabr.sexp: a list of
// (forward expiry alpha beta nu rho strike lognormal-vol normal-vol).
#include <ql/termstructures/volatility/sabr.hpp>
#include <fstream>
#include <iomanip>

using namespace QuantLib;

int main(int, char** argv) {
    struct Case { Real forward, expiry, alpha, beta, nu, rho; };
    const Case cases[] = {
        {0.03, 1.0, 0.02, 0.5, 0.4, -0.3},
        {0.03, 5.0, 0.015, 0.3, 0.6, 0.2},
        {100.0, 0.5, 2.0, 0.5, 0.5, -0.6},
        {100.0, 2.0, 0.25, 1.0, 0.8, -0.4},
        {0.05, 10.0, 0.05, 0.0, 0.3, 0.1},
        {1.2, 0.25, 0.1, 0.7, 1.2, 0.5},
    };
    const Real moneyness[] = {0.5, 0.7, 0.85, 0.95, 0.99, 1.0, 1.01, 1.05, 1.2, 1.5, 2.0};
    std::ofstream out(argv[1]);
    out << ";;;; Generated by tests/fixtures/generate_sabr.cpp from QuantLib's sabrVolatility.\n"
        << ";;;; (forward expiry alpha beta nu rho strike lognormal-vol normal-vol). Do not edit.\n(\n"
        << std::setprecision(17);
    for (const auto& c : cases) {
        for (Real m : moneyness) {
            Real k = c.forward * m;
            Real ln = sabrVolatility(k, c.forward, c.expiry, c.alpha, c.beta, c.nu, c.rho,
                                     VolatilityType::ShiftedLognormal);
            Real n = sabrVolatility(k, c.forward, c.expiry, c.alpha, c.beta, c.nu, c.rho,
                                    VolatilityType::Normal);
            out << " (" << c.forward << "d0 " << c.expiry << "d0 " << c.alpha << "d0 " << c.beta
                << "d0 " << c.nu << "d0 " << c.rho << "d0 " << k << "d0 " << ln << "d0 " << n
                << "d0)\n";
        }
    }
    out << ")\n";
    return 0;
}
